-- History pivot / #185: Era das Revoluções
-- Generated by generators/emit_trail_sql.py from generators/trail_era_revolucoes.py.
-- Idempotent. One transaction. Pair with matching .rollback.sql.
-- DO NOT apply without owner go-ahead. Dry-run with BEGIN + RAISE EXCEPTION.

BEGIN;

INSERT INTO public.modulos (ordem, titulo, emoji, cor, categoria_id, descricao)
SELECT 23, 'Era das Revoluções', '⚖️', '#DC2626', 1, 'Do Iluminismo às revoluções Americana, Francesa e Haitiana, de Napoleão às independências latino-americanas, da fábrica aos nacionalismos: o longo século XIX que moldou o mundo moderno.'
WHERE NOT EXISTS (SELECT 1 FROM public.modulos WHERE titulo = 'Era das Revoluções');

CREATE TEMP TABLE _seed_trail AS
SELECT id AS modulo_id FROM public.modulos WHERE titulo = 'Era das Revoluções';

INSERT INTO public.niveis (modulo_id, ordem, titulo)
SELECT t.modulo_id, v.ordem, v.titulo
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 'Nível 1 - Ideias e Atlântico'),
  (2, 'Nível 2 - Napoleão e Américas'),
  (3, 'Nível 3 - Indústria e ideologias'),
  (4, 'Nível 4 - Nações e impérios')
) AS v(ordem, titulo)
WHERE NOT EXISTS (
  SELECT 1 FROM public.niveis n WHERE n.modulo_id = t.modulo_id AND n.ordem = v.ordem
);

INSERT INTO public.submodulos (modulo_id, nivel_id, ordem, titulo, data_liberacao_desde_inicio, imagem_url)
SELECT t.modulo_id, n.id, v.ordem, v.titulo, 0, NULL
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 1, 'Iluminismo e esfera pública'),
  (1, 2, 'Revolução Americana'),
  (1, 3, 'Revolução Francesa'),
  (2, 4, 'Napoleão e a Europa'),
  (2, 5, 'Independências na América Latina'),
  (2, 6, 'Haiti e a revolução escrava'),
  (3, 7, 'Revolução Industrial'),
  (3, 8, 'Trabalho, classe e cidade'),
  (3, 9, 'Liberalismo e socialismo'),
  (4, 10, 'Nacionalismos do século XIX'),
  (4, 11, 'Impérios e a Questão do Oriente'),
  (4, 12, '1848 e o longo século')
) AS v(nivel_ordem, ordem, titulo)
JOIN public.niveis n ON n.modulo_id = t.modulo_id AND n.ordem = v.nivel_ordem
WHERE NOT EXISTS (
  SELECT 1 FROM public.submodulos s WHERE s.modulo_id = t.modulo_id AND s.ordem = v.ordem
);

INSERT INTO public.licoes (submodulo_id, ordem, titulo, emoji, conteudo)
SELECT s.id, 1, s.titulo, '⚖️',
       jsonb_build_object('preview', v.preview)
FROM _seed_trail t
JOIN public.submodulos s ON s.modulo_id = t.modulo_id
JOIN (VALUES
  (1, 'No século XVIII, círculos letrados europeus passaram a questionar tradição, absolutismo e privilégios em nome da razão, da tolerância e da crítica pública. Montesquieu defendeu a separação dos poderes; Voltaire atacou a intolerância; Rousseau pensou a soberania popular; a Encyclopédie de Diderot e d''Alembert reuniu saberes. Cafés, salões, gazetas e livros formaram uma esfera pública — ampla para a época, mas restrita a quem sabia ler e circulava nesses espaços. O mesmo Iluminismo conviveu com escravidão, racismo e exclusão das mulheres.'),
  (2, 'Depois da Guerra dos Sete Anos (1756–1763), a Grã-Bretanha cobrou novos impostos nas Treze Colônias (Lei do Selo, tarifa do chá). O lema ''sem representação, sem tributação'' alimentou boicotes, protestos e o Congresso Continental. A guerra começou em 1775; a Declaração de Independência é de 1776; o apoio francês e a vitória em Yorktown (1781) selaram o desfecho. A Constituição de 1787 criou uma república federal com separação de poderes — que preservou a escravidão e excluiu indígenas, mulheres e a maioria dos negros da cidadania plena.'),
  (3, 'Crise fiscal, desigualdade entre os três estados e más colheitas levaram à convocação dos Estados Gerais (1789). Vieram a Assembleia Nacional, a queda da Bastilha, o fim dos privilégios feudais e a Declaração dos Direitos do Homem e do Cidadão. A monarquia constitucional cedeu à República (1792); Luís XVI foi executado em 1793 e o Terror jacobino perseguiu supostos inimigos da Revolução. O processo ampliou direitos políticos e a ideia de cidadania, mas também gerou violência, guerra e exclusões — como a das mulheres.'),
  (4, 'Napoleão Bonaparte chegou ao poder com o golpe do 18 Brumário (1799), foi Cônsul e, em 1804, imperador. Consolidou conquistas da Revolução — Código Civil, administração centralizada — e governou de modo autoritário, com censura e guerras de conquista. Venceu em Austerlitz (1805), decretou o Bloqueio Continental (1806), fracassou na Rússia (1812) e caiu em Waterloo (1815). O Congresso de Viena (1814–1815) tentou restaurar monarquias e um equilíbrio entre potências, sem apagar as ideias liberais e nacionais que as guerras haviam espalhado.'),
  (5, 'A invasão napoleônica da Península Ibérica (1807–1808) abriu uma crise de legitimidade nos impérios ibéricos. Na América espanhola, juntas locais, criollos e líderes como Bolívar e San Martín conduziram guerras que, até Ayacucho (1824), encerraram o domínio espanhol continental — com a fragmentação em várias repúblicas. No Brasil, a corte portuguesa se instalou no Rio (1808) e a independência (1822) manteve a monarquia e a escravidão. Indígenas, negros e mulheres participaram das lutas, mas elites crioulas dominaram os novos Estados.'),
  (6, 'Saint-Domingue era a colônia francesa mais lucrativa do Caribe, sustentada por centenas de milhares de africanos escravizados. A insurreição de agosto de 1791 virou revolução: a escravidão foi abolida na colônia (1793) e, depois, pela Convenção francesa (1794); Toussaint Louverture liderou os exércitos e o governo; a expedição enviada por Napoleão em 1802 para restaurar a escravidão foi derrotada. Em 1º de janeiro de 1804, Dessalines proclamou o Haiti, primeiro Estado fundado por ex-escravizados. Potências escravistas o isolaram, e a França só reconheceu a independência em 1825, em troca de uma pesada indenização.'),
  (7, 'A partir de meados do século XVIII, a Inglaterra combinou carvão e ferro acessíveis, capital comercial, mercados coloniais, inovações técnicas e mão de obra deslocada do campo. Máquinas têxteis, a máquina a vapor aperfeiçoada por Watt, ferrovias e fábricas mudaram a escala e o ritmo da produção. O processo foi gradual e desigual: chegou à Bélgica, à França, aos Estados Unidos e à Alemanha ao longo do século XIX, e uma ''segunda'' fase (aço, eletricidade, química) veio depois de 1870. O algodão que abastecia as fábricas dependia do trabalho escravizado nas Américas.'),
  (8, 'A fábrica impôs disciplina de relógio, salários baixos e jornadas longas, com amplo uso de trabalho de mulheres e crianças. Cidades como Manchester cresceram rápido, com cortiços, pouca água potável e epidemias. Surgiram resistências: o ludismo (1811–1816), os sindicatos, o cartismo e as greves. Leis como o Factory Act de 1833 e o Ten Hours Act (1847) limitaram abusos. A noção de classe trabalhadora como sujeito político nasceu junto com debates sobre reforma urbana e saúde pública.'),
  (9, 'O liberalismo defendia liberdades individuais, propriedade, governo limitado e livre mercado — de Locke a Adam Smith e Stuart Mill. Diante da miséria industrial, socialistas como Owen e Saint-Simon propuseram cooperação e planejamento; Marx e Engels, no Manifesto Comunista (1848), viram a história como luta de classes e o capitalismo como sistema a ser superado. Anarquistas, como Proudhon e Bakunin, desconfiavam de todo Estado. Esses debates organizaram partidos, sindicatos e a Primeira Internacional (1864).'),
  (10, 'Depois de 1815, a ideia de nação — língua, história, território — mobilizou povos sob impérios e Estados fragmentados. A Itália se unificou entre 1859 e 1870, com Cavour, Garibaldi e o Piemonte-Sardenha; a Alemanha, sob a Prússia de Bismarck, em guerras contra Dinamarca, Áustria e França, até 1871. O nacionalismo podia libertar e unir, mas também excluir minorias e alimentar rivalidades. Escolas, exércitos, língua padrão e símbolos ajudaram a construir Estados nacionais.'),
  (11, 'O Império Otomano perdeu território nos Bálcãs enquanto Rússia, Grã-Bretanha, França e Áustria disputavam influência — a chamada Questão do Oriente. Os gregos lutaram pela independência (1821–1830); a Guerra da Crimeia (1853–1856) opôs a Rússia aos otomanos, britânicos e franceses; o Congresso de Berlim (1878) redesenhou os Bálcãs. Os otomanos tentaram reformas internas no Tanzimat. No mesmo século, a Europa ampliava domínios na Ásia e na África, rumo à Conferência de Berlim (1884–1885) e à partilha africana.'),
  (12, 'Em 1848, revoluções liberais, nacionais e sociais — a Primavera dos Povos — varreram a França, os Estados alemães, o Império Habsburgo e a Itália. Em Paris, Luís Filipe caiu e a Segunda República adotou o sufrágio masculino; ao fim, Luís Napoleão chegou ao poder. Muitas revoltas foram reprimidas, mas a servidão foi abolida nos domínios habsburgos e as ideias de constituição, nação e direitos sociais permaneceram. Eric Hobsbawm chamou de ''longo século XIX'' o período de 1789 a 1914, entre as revoluções e a Primeira Guerra Mundial.')
) AS v(sub_ordem, preview) ON v.sub_ordem = s.ordem
WHERE NOT EXISTS (SELECT 1 FROM public.licoes l WHERE l.submodulo_id = s.id);

