  SELECT p.id, 'quem-sou-eu', 'Quem sou eu?', '{"header": "Quem sou eu?", "dica_1": "Sou sobrinho de Napoleão Bonaparte.", "dica_2": "Fui eleito presidente da Segunda República francesa em 1848.", "dica_3": "Dei um autogolpe em 1851 e proclamei o Segundo Império no ano seguinte.", "dica_4": "Perdi o trono após a derrota em Sedan, em 1870.", "resposta_certa": "Napoleão III", "sinonimos_aceitos": ["Luís Napoleão Bonaparte", "Luis Napoleao Bonaparte", "Napoleao III"], "explicacao": "Luís Napoleão chegou ao poder pelo voto, em 1848, e consolidou um regime autoritário; sua queda em 1870 abriu caminho à Terceira República.", "tipo": "quem_sou_eu"}'::jsonb, 'Napoleão III',
         'Luís Napoleão chegou ao poder pelo voto, em 1848, e consolidou um regime autoritário; sua queda em 1870 abriu caminho à Terceira República.', 'Revise o conceito e tente de novo.', 'medio', true
  FROM picked p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.concept_game_items cgi WHERE cgi.concept_id = p.id AND cgi.game_type = 'quem-sou-eu'
  )
  RETURNING concept_id
)
INSERT INTO public.submodulo_pares (
  submodulo_id, ordem, preview_hook, game_type, content_type,
  cognitive_demand, concept_id, licao_id
)
SELECT s.id, 4, 'Quem sou eu?', 'quem-sou-eu', 'conceito',
       'media', p.id, l.id
FROM picked p
JOIN _seed_trail t ON true
JOIN public.submodulos s ON s.modulo_id = t.modulo_id AND s.ordem = 12
JOIN public.licoes l ON l.submodulo_id = s.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.submodulo_pares sp WHERE sp.submodulo_id = s.id AND sp.ordem = 4
);

DO $$
DECLARE
  v_mod bigint; v_subs int; v_pairs int;
BEGIN
  SELECT modulo_id INTO v_mod FROM _seed_trail;
  SELECT count(*) INTO v_subs FROM public.submodulos WHERE modulo_id = v_mod;
  SELECT count(*) INTO v_pairs FROM public.submodulo_pares sp
    JOIN public.submodulos s ON s.id = sp.submodulo_id WHERE s.modulo_id = v_mod;
  IF v_subs <> 12 OR v_pairs <> 48 THEN
    RAISE EXCEPTION 'trail seed incomplete: submodules=%, pairs=% (want 12/48)', v_subs, v_pairs;
  END IF;
END $$;

DROP TABLE _seed_trail;
COMMIT;
